window.AUTH=window.AUTH||{};window.AUTH["17-1268"]={"d":"17-1268","id":"2019/17-1268","n":"Opati v. Republic of Sudan","briefs":[{"k":"petitioner","label":"Brief of petitioners Monicah Okoba Opati, et al.","date":"2019-09-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/116092/20190917165629051_Brief.pdf","side":"pet","n":31},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-09-24","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/116903/20190924182439063_17-1268tsacUnitedStates.pdf","side":"us","n":51},{"k":"respondent","label":"Brief of respondents Republic of Sudan, et al.","date":"2019-11-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/123381/20191122141432868_Brief%20for%20Respondents_17-1268.pdf","side":"res","n":61},{"k":"reply","label":"Reply of petitioners Monicah Okoba Opati, et al.","date":"2019-12-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/126578/20191223144202246_Reply%20Brief%20TO%20FILE.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=434","tr":true,"items":[{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Bakhtiar v. Islamic Republic of Iran","cite":"668 F.3d 773","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/668/773/","by":{"0":"44","3":"15"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"0":"25-26, 33","1":"20"}},{"t":"case","label":"Cicippio-Puleo v. Islamic Republic of Iran","cite":"353 F.3d 1024","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/353/1024/","op":1,"by":{"0":"8, 11","1":"3, 26, 27","2":"8, 43, 44"}},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation of N.Y.","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"0":"55","3":"17"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Eisenfeld v. Islamic Republic of Iran","cite":"172 F. Supp. 2d 1","y":2000,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/172/1/","by":{"0":"5","1":"23"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"38-39","1":"15, 22"}},{"t":"case","label":"Flatow v. Islamic Republic of Iran","cite":"999 F. Supp. 1","y":1998,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./999/1/","ar":4,"by":{"0":"5, 31, 43","1":"23"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"op":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Cited Authorities Page Franklin v. Gwinnett Cnty. Public Schools","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"sum":"Justice Byron R. White wrote the Court's unanimous decision, holding that monetary damages are available under Title IX because there is a presumption that any appropriate relief is available to remedy the violation of a federal right. In this case, back pay and prospective relief were not sufficient remedies.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Hughes Aircraft Co. v. United States ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"sum":"The Court held that, because the 1986 amendment does not apply retroactively to qui tam suits regarding allegedly false claims submitted prior to its enactment, Schumer's action should have been dismissed, as required by the pre-1986 version of the FCA.","sumSrc":"Oyez","by":{"0":"38","1":"18, 30, 32","2":"36, 39"}},{"t":"case","label":"Jenco v. Islamic Republic of Iran","cite":"154 F. Supp. 2d 27","y":2001,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/154/27/","by":{"0":"5","1":"23"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"op":5,"ar":29,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"1, 2, 3, 5, 6, 7, 10, 11, 12, 16, 18"}},{"t":"case","label":"Lewis v. Clarke","cite":"137 S. Ct. 1285","y":2017,"id":"2016/15-1500","sc":1,"op":2,"sum":"The Court determined that tribal sovereign immunity is not implicated in a suit against a tribal employee in his individual capacity, and an indemnification provision cannot extend tribal sovereign immunity to conduct that it would not otherwise cover.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"North Star Steel Co. v. Thomas","cite":"515 U.S. 29","y":1995,"id":"1994/94-834","sc":1,"op":7,"sum":"The Court held that State law is the proper source of the limitations period for civil actions brought to enforce WARN. Where a federal statute fails to provide any limitations period for a new cause of action, the Court noted that its longstanding practice has been to borrow the limitations period from the most closely analogous state statute.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"374 F. Supp. 2d 1","y":2005,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/374/1/","by":{"0":"7"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"412 F. Supp. 2d 99","y":2006,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/412/99/","by":{"0":"7","1":"6"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"531 F.3d 884","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/531/884/","by":{"0":"7"}},{"t":"case","label":"Republic of Argentina v. NML Capital, Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Cited Authorities Page Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"op":3,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"1, 2, 5, 6, 7, 8, 9, 10, 18"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"0":"32, 54","1":"21"}},{"t":"case","label":"Republic of Sudan v. Owens","cite":"194 A.3d 38","y":2018,"court":"D.C.","url":"https://www.courtlistener.com/c/A.3d/194/38/","by":{"0":"16"}},{"t":"case","label":"Rimkus v. Islamic Republic of Iran","cite":"750 F. Supp. 2d 163","y":2010,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/750/163/","by":{"0":"45","3":"15"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"0":"23, 46","2":"22, 58"}},{"t":"case","label":"SAS Institute Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"op":2,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Scott v. Donald","cite":"165 U.S. 58","y":1897,"id":"scdb/1896-231","sc":1,"sum":"Vliere'a-suit is brought against defendants who claim to act as officers of a State and under color of an unconstitutional statute commit acts of wrong and injury to the property of tlio plaintiff, to recover money or property in their hands unlawfully taken by them in behalf of the State, or for compensation for damages, such suit is not an action against the State within the meaning of the Eleventh Amendment to …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"United States v. Rahman","cite":"189 F.3d 88","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/189/88/","by":{"0":"6"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":2,"ar":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"27, 37-38, 41","1":"16, 17","2":"5, 36","3":"9"}},{"t":"case","label":"Brief for the United States, Acree v. Republic of Iraq","cite":"2005 WL 682164","y":2005,"court":"Mar. 21","by":{"0":"26, 29-30"}},{"t":"case","label":"Brief for the United States, Republic of Austria v. Altmann","cite":"2003 WL 22811828","y":2003,"court":"Nov. 14","by":{"0":"37"}},{"t":"case","label":"AT&T Corp. v. Hulteen","cite":"556 U.S. 701","y":2009,"id":"2008/07-543","sc":1,"sum":"The Court held that a company does not violate the Pregnancy Discrimination Act (PDA) or Title VII when it denies retirement benefits to women who took a temporary disability leave while pregnant when the leave was taken before the PDA came into effect.","sumSrc":"Oyez","by":{"1":"22","2":"47"}},{"t":"case","label":"Ditullio v. Boehm","cite":"662 F.3d 1091","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/662/1091/","by":{"1":"25"}},{"t":"case","label":"Foger ty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"op":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"(III) Cases—Continued: Gross v. Weber","cite":"186 F.3d 1089","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/186/1089/","op":1,"ar":1,"by":{"1":"25, 26"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"15, 22","2":"47"}},{"t":"case","label":"Koch v. SEC","cite":"793 F.3d 147","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/793/147/","by":{"1":"26"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"ar":1,"sum":"The Court held that the 1996 version of the federal habeas statute, as to standards affecting the entitlement of state prisoners to federal habeas corpus relief, does not to apply to non-capital habeas corpus cases that were pending when the Act was enacted.","sumSrc":"Oyez","by":{"1":"22","2":"41, 46, 47","3":"13"}},{"t":"law","label":"and rules: Aimee’s Law, Pub. L. No. 106-386","url":"https://www.govinfo.gov/link/plaw/106/public/386","by":{"1":"23, 25","2":"6, 16"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(a)"],"by":{"1":"15"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681. Sex","tname":"Education","by":{"1":"25"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(7)","(a)(7)(2000)","(a)(7)(2006)","(e)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"1":"23, 23, 3, 5, passim","2":"passim, 8, passim, 54"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"1":"2","2":"5"}},{"t":"usc","label":"28 U.S.C. § 1605A","url":"https://www.law.cornell.edu/uscode/text/28/1605A","subs":["(a)","(a)(1)","(a)(2)(A)(i)","(a)(2)(A)(i)(II)","(c)","(a)(2)","(a)(2)(A)(ii)","(b)","(h)(7)"],"stext":{"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","paras":[[0,"(a) In General.—"],[1,"(1) No immunity.—A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case not otherwise covered by this chapter in which money damages are sought against a foreign state for personal injury or death that was caused by an act of torture, extrajudicial killing, aircraft sabotage, hostage taking, or the provision of material support or resources for such an act if such act or provision of material support or resources is engaged in by an official, employee, or agent of such foreign state while acting within the scope of his or her office, employment, or agency."],[1,"(2) Claim heard.—The court shall hear a claim under this section if—"],[2,"(A)(i)(I) the foreign state was designated as a state sponsor of terrorism at the time the act described in paragraph (1) occurred, or was so designated as a result of such act, and, subject to subclause (II), either remains so designated when the claim is filed under this section or was so designated within the 6-month period before the claim is filed under this section; or"],[2,"(II) in the case of an action that is refiled under this section by reason of section 1083(c)(2)(A) of the National Defense Authorization Act for Fiscal Year 2008 or is filed under this section by reason of section 1083(c)(3) of that Act, the foreign state was designated as a state sponsor of terrorism when the original action or the related action under section 1605(a)(7) (as in effect before the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) was filed;"],[2,"(ii) the claimant or the victim was, at the time the act described in paragraph (1) occurred—"],[3,"(I) a national of the United States;"],[3,"(II) a member of the armed forces; or"],[3,"(III) otherwise an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment; and"],[2,"(iii) in a case in which the act occurred in the foreign state against which the claim has been brought, the claimant has afforded the foreign state a reasonable opportunity to arbitrate the claim in accordance with the accepted international rules of arbitration; or"],[2,"(B) the act described in paragraph (1) is related to Case Number 1:00CV03110 (EGS) in the United States District Court for the District of Columbia."],[0,"(b) Limitations.—An action may be brought or maintained under this section if the action is commenced, or a related action was commenced under section 1605(a)(7) (before the date of the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) not later than the latter of—"],[1,"(1) 10 years after April 24, 1996; or"],[1,"(2) 10 years after the date on which the cause of action arose."],[0,"(c) Private Right of Action.—A foreign state that is or was a state sponsor of terrorism as described in subsection (a)(2)(A)(i), and any official, employee, or agent of that foreign state while acting within the scope of his or her office, employment, or agency, shall be liable to—"],[1,"(1) a national of the United States,"],[1,"(2) a member of the armed forces,"],[1,"(3) an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment, or"],[1,"(4) the legal representative of a person described in paragraph (1), (2), or (3),"],[0,"for personal injury or death caused by acts described in subsection (a)(1) of that foreign state, or of an official, employee, or agent of that foreign state, for which the courts of the United States may maintain jurisdiction under this section for money damages. In any such action, damages may include economic damages, solatium, pain and suffering, and punitive damages. In any such action, a foreign state shall be vicariously liable for the acts of its officials, employees, or agents."],[0,"(d) Additional Damages.—After an action has been brought under subsection (c), actions may also be brought for reasonably foreseeable property loss, whether insured or uninsured, third party liability, and loss claims under life and property insurance policies, by reason of the same acts on which the action under subsection (c) is based."],[0,"(e) Special Masters.—"],[1,"(1) In general.—The courts of the United States may appoint special masters to hear damage claims brought under this section."],[1,"(2) Transfer of funds.—The Attorney General shall transfer, from funds available for the program under section 1404C of the Victims of Crime Act of 1984 (42 U.S.C. 10603c),1 to the Administrator of the United States district court in which any case is pending which has been brought or maintained under this section such funds as may be required to cover the costs of special masters appointed under paragraph (1). Any amount paid in compensation to any such special master shall constitute an item of court costs."],[0,"(f) Appeal.—In an action brought under this section, appeals from orders not conclusively ending the litigation may only be taken pursuant to section 1292(b) of this title."],[0,"(g) Property Disposition.—"],[1,"(1) In general.—In every action filed in a United States district court in which jurisdiction is alleged under this section, the filing of a notice of pending action pursuant to this section, to which is attached a copy of the complaint filed in the action, shall have the effect of establishing a lien of lis pendens upon any real property or tangible personal property that is—"],[2,"(A) subject to attachment in aid of execution, or execution, under section 1610;"],[2,"(B) located within that judicial district; and"],[2,"(C) titled in the name of any defendant, or titled in the name of any entity controlled by any defendant if such notice contains a statement listing such controlled entity."],[1,"(2) Notice.—A notice of pending action pursuant to this section shall be filed by the clerk of the district court in the same manner as any pending action and shall be indexed by listing as defendants all named defendants and all entities listed as controlled by any defendant."],[1,"(3) Enforceability.—Liens established by reason of this subsection shall be enforceable as provided in chapter 111 of this title."],[0,"(h) Definitions.—For purposes of this section—"],[1,"(1) the term \"aircraft sabotage\" has the meaning given that term in Article 1 of the Convention for the Suppression of Unlawful Acts Against the Safety of Civil Aviation;"],[1,"(2) the term \"hostage taking\" has the meaning given that term in Article 1 of the International Convention Against the Taking of Hostages;"],[1,"(3) the term \"material support or resources\" has the meaning given that term in section 2339A of title 18;"],[1,"(4) the term \"armed forces\" has the meaning given that term in section 101 of title 10;"],[1,"(5) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(6) the term \"state sponsor of terrorism\" means a country the government of which the Secretary of State has determined, for purposes of section 6(j) of the Export Administration Act of 1979 (50 U.S.C. App. 2405(j)),1 section 620A of the Foreign Assistance Act of 1961 (22 U.S.C. 2371), section 40 of the Arms Export Control Act (22 U.S.C. 2780), or any other provision of law, is a government that has repeatedly provided support for acts of international terrorism; and"],[1,"(7) the terms \"torture\" and \"extrajudicial killing\" have the meaning given those terms in section 3 of the Torture Victim Protection Act of 1991 (28 U.S.C. 1350 note)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605A?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":5,"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"1":"3, 3, 3, 3, 3, 3, 19, 33, 5, 20, 27, 4, 6, 18, 19, 11, 13, 4, 6, 13, 19, 32, 21","2":"passim, passim, 16, 21, 10, 4, 53, 58, 59, 17, 28, 29, passim, 21, 54","3":"23, 1, 14, 23, 21"}},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","stext":{"head":"§1606. Extent of liability","paras":[[0,"As to any claim for relief with respect to which a foreign state is not entitled to immunity under section 1605 or 1607 of this chapter, the foreign state shall be liable in the same manner and to the same extent as a private individual under like circumstances; but a foreign state except for an agency or instrumentality thereof shall not be liable for punitive damages; if, however, in any case wherein death was caused, the law of the place where the action or omission occurred provides, or has been construed to provide, for damages only punitive in nature, the foreign state shall be liable for actual or compensatory damages measured by the pecuniary injuries resulting from such death which were incurred by the persons for whose benefit the action was brought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1606?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§1606. Extent of liability","tname":"Judiciary and Judicial Procedure","by":{"1":"3","2":"passim"}},{"t":"usc","label":"22 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/22/7101","by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"23","2":"9"}},{"t":"usc","label":"18 U.S.C. § 1595","url":"https://www.law.cornell.edu/uscode/text/18/1595","by":{"1":"25"}},{"t":"reg","label":"58 Fed. Reg. 52,523","url":"https://www.govinfo.gov/link/fr/58/52523","by":{"1":"5"}},{"t":"reg","label":"69 Fed. Reg. 58,793","url":"https://www.govinfo.gov/link/fr/69/58793","by":{"1":"21"}},{"t":"reg","label":"73 Fed. Reg. 6571","url":"https://www.govinfo.gov/link/fr/73/6571","by":{"1":"21"}},{"t":"case","label":"Agudas Chasidei Chabad of U.S. v. Russian Federation","cite":"528 F.3d 934","y":2008,"court":"D.C.Cir.","url":"https://www.courtlistener.com/c/F.3d/528/934/","by":{"2":"27-28"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"2":"21","3":"20"}},{"t":"case","label":"Bettis v. Islamic Republic of Iran","cite":"315 F.3d 325","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/315/325/","by":{"2":"5, 56"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"op":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"2":"19, 27, 28","3":"21"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"Dolan v. U.S. Postal Serv.","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"op":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Fort Bend Cty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28, 29"}},{"t":"case","label":"Graham & Foster v. Goodcell","cite":"282 U.S. 409","y":1931,"id":"scdb/1930-023","sc":1,"sum":"(1) Section 611 *applies retroactively to claims for refunds filed before the enactment of the statute. P. 418. (2) Section 611 applies tb involuntary, as well as to voluntary, payments by taxpayers. P. 420. (3) The \"stay\" of collection contemplated by § 611 includes a postponement not required by statute or judicial order but voluntary on the part of the Treasury. \"P. 421. (4) The fact that a claim in abatement was …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Kadic v. Karadžić","cite":"70 F.3d 232","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/70/232/","by":{"2":"23"}},{"t":"case","label":"Lake Country Estates, Inc. v. Tahoe Regional Planning Agency","cite":"440 U.S. 391","y":1979,"id":"1978/77-1327","sc":1,"sum":"California and Nevada entered into a Compact, later consented to by Congress, to create respondent Tahoe Regional Planning Agency (TRPA) to coordinate and regulate development in the Lake Tahoe Basin resort area and to conserve its natural resources. The Compact authorized TRPA to adopt and enforce a regional plan for land use, transportation, conservation, recreation, and public services. Petitioners, Basin …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Leibovitch v. Islamic Republic of Iran","cite":"697 F.3d 561","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/561/","by":{"2":"56"}},{"t":"case","label":"Martin v. Hadix","cite":"527 U.S. 343","y":1999,"id":"1998/98-262","sc":1,"ar":2,"sum":"The Court held that the Prison Litigation Reform Act of 1995 \"limits attorney's fees for post-judgment monitoring services performed after the PLRA's effective date, but does not limit fees for monitoring performed before that date.\" \"To impose the new standards now, for work performed before the PLRA became effective, would upset the reasonable expectations of the parties,\" Justice O'Connor wrote for the Court.","sumSrc":"Oyez","by":{"2":"46, 47","3":"13"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Nat’l Ass’n of R.R. Passengers","cite":"414 U.S. 453","y":1974,"id":"1973/72-1289","sc":1,"sum":"Section: 307 (a), in light of its express language, and the legislative history of that provision 'and of the Act as a *whole, provides the exclusive remedies for breaches of any duties or obligations imposed by the Act, and no additional private cause of action to enforce compliance with the Act can properly be inferred. Pp. 455-465. 154 U. S. App. D. C.-214, 475 F. 2d 325,.reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"59"}},{"t":"case","label":"P & V Enters. v. U.S. Army Corps of Eng’rs","cite":"516 F.3d 1021","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/516/1021/","sum":"Holding that §2401(a) is jurisdictional.","sumSrc":"brief:2","by":{"2":"30"}},{"t":"case","label":"Peterson v. Islamic Republic of Iran","cite":"515 F. Supp. 2d 25","y":2007,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/515/25/","by":{"2":"56"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"2":"22, 58"}},{"t":"case","label":"Soc’y for Propagation of the Gospel v. Wheeler","cite":"22 F. Cas. 756","y":1814,"court":"CCD N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./22/756/","by":{"2":"35"}},{"t":"case","label":"United States v. Wong","cite":"135 S. Ct. 1625","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1625/","sc":1,"by":{"2":"28-29, 30"}},{"t":"case","label":"Wash. All. of Tech. Workers v. U.S. Dep’t of Homeland Sec.","cite":"892 F.3d 332","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/332/","op":4,"sum":"Stating §2401(a) is jurisdictional.","sumSrc":"brief:2","by":{"2":"30"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"51"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"head":"§1350. Alien's action for tort","tname":"Judiciary and Judicial Procedure","by":{"2":"6, 21-22, 54","3":"21"}},{"t":"usc","label":"28 U.S.C. § 1607","url":"https://www.law.cornell.edu/uscode/text/28/1607","by":{"2":"passim"}},{"t":"usc","label":"28 U.S.C. § 1610","url":"https://www.law.cornell.edu/uscode/text/28/1610","subs":["(g)"],"by":{"2":"11, 57, 58, 9"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)","(b)"],"by":{"2":"29, 30, 29"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"2":"8, 44"}},{"t":"law","label":"Pub. L. No. 102-256","url":"https://www.govinfo.gov/link/statute/106/73","by":{"2":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(4)","(b)(6)"],"by":{"2":"15, 15, 16"}},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"sum":"The Court affirmed the judgment of the Circuit Court and ruled that the District Court was within its discretion when it dismissed Day's petition.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Edelman v. Lynchburg Coll.","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"sum":"The Court held that the EEOC's relation-back regulation was an unassailable interpretation of Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Musacchio v. United States","cite":"136 S. Ct. 709","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Oliver v. Mustafa","cite":"929 A.2d 873","y":2007,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/929/873/","by":{"3":"19"}},{"t":"case","label":"PGA Tour, Inc. v. Martin","cite":"532 U.S. 661","y":2001,"id":"2000/00-24","sc":1,"sum":"The Court held that Title III of the ADA, by its plain terms, prohibits the PGA from denying Martin equal access to its tours on the basis of his disability and that allowing Martin to use a cart, despite the walking rule, is not a modification that would \"fundamentally alter the nature\" of the game. \"The purpose of the walking rule is... not compromised in the slightest by allowing Martin to use a cart,\" wrote Justice Stevens, noting Martin's fatiguing disability.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Price v. Socialist People’s Libyan Arab Jamahiriya","cite":"294 F.3d 82","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/294/82/","by":{"3":"6, 16"}},{"t":"case","label":"Principality of Monaco v. Mississippi","cite":"292 U.S. 313","y":1934,"id":"scdb/1933-124","sc":1,"sum":"1. This Court has no jurisdiction of a suit brought by a foreign State against a State of the Union without her consent. Pp. 320, 330.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"op":5,"sum":"The Court held that the Fifteenth Amendment is a valid constitutional basis for the Voting Rights Act of 1965.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"17"}},{"t":"usc","label":"22 U.S.C. § 8772","url":"https://www.law.cornell.edu/uscode/text/22/8772","by":{"3":"8"}},{"t":"law","label":"Pub. L. No. 114-122","url":"https://www.govinfo.gov/link/plaw/114/public/122","by":{"3":"7"}}]};